use vstd::prelude::*;

verus! {
    /// Append `elem` to the end of vector `v`.
    ///
    /// Ensures that:
    /// 1) the resulting vector has length `v.len() + 1`,
    /// 2) for all valid indices `i < v.len()`, `result[i] == v[i]`,
    /// 3) the final element `result[v.len()] == elem`.
    fn append(v: &Vec<u64>, elem: u64) -> Vec<u64>
        ensures
            // Result length is original length + 1
            result.len() == v.len() + 1,

            // All original elements are preserved
            forall |i: usize| i < v.len() ==> result[i] == v[i],

            // The new element sits at the end
            result[v.len()] == elem,
    {
        // Pre‐allocate a new vector with enough capacity for v.len() + 1 elements
        let mut result = Vec::with_capacity(v.len() + 1);
        // Copy over all elements from the original vector
        result.extend_from_slice(v);
        // Append the new element
        result.push(elem);
        result
    }
}

